function validate([n, connections]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 100000.';
  const most = Math.min(n * (n - 1) / 2, 100000);
  if (connections.length < 1 || connections.length > most) return 'connections needs between 1 and min(n * (n - 1) / 2, 100000) cables.';
  const seen = new Set();
  for (const pair of connections) {
    if (pair.length !== 2) return 'Each connection is a pair [a, b].';
    const [a, b] = pair;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Computer labels are between 0 and n - 1.';
    if (a === b) return 'A cable cannot link a computer to itself.';
    const key = Math.min(a, b) * 100000 + Math.max(a, b);
    if (seen.has(key)) return 'Each pair of computers is linked at most once.';
    seen.add(key);
  }
  return null;
}

