function makeConnected(n, connections) {
  // Count clusters with DFS, then check whether the spare cables cover the bridges needed.
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of connections) { adj[a].push(b); adj[b].push(a); }
  const seen = new Array(n).fill(false);
  let clusters = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    clusters++;
    const stack = [s];
    seen[s] = true;
    while (stack.length) {
      const u = stack.pop();
      for (const v of adj[u]) if (!seen[v]) { seen[v] = true; stack.push(v); }
    }
  }
  const treeEdges = n - clusters;
  const spare = connections.length - treeEdges;
  return spare >= clusters - 1 ? clusters - 1 : -1;
}

