function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(2, 8);
    const pairs = [];
    for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) pairs.push(rand() < 0.5 ? [a, b] : [b, a]);
    for (let i = pairs.length - 1; i > 0; i--) { const j = int(0, i); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
    return [n, pairs.slice(0, int(1, pairs.length))];
  }
  // Large: split the computers into groups, wire each group as a random tree, then add spare cables inside groups.
  const n = int(800, 1900);
  const groups = int(1, 60);
  const label = Array.from({ length: n }, (_, i) => i < groups ? i : int(0, groups - 1));
  const members = Array.from({ length: groups }, () => []);
  for (let v = 0; v < n; v++) members[label[v]].push(v);
  const used = new Set(), connections = [];
  const add = (a, b) => {
    const key = Math.min(a, b) * 100000 + Math.max(a, b);
    if (a === b || used.has(key)) return false;
    used.add(key);
    connections.push([a, b]);
    return true;
  };
  for (const list of members) for (let i = 1; i < list.length; i++) add(list[i], list[int(0, i - 1)]);
  const target = Math.min(2000, connections.length + int(0, 2000 - connections.length));
  for (let tries = 0; connections.length < target && tries < 20000; tries++) {
    const list = members[label[int(0, n - 1)]];
    if (list.length > 1) add(list[int(0, list.length - 1)], list[int(0, list.length - 1)]);
  }
  for (let i = connections.length - 1; i > 0; i--) { const j = int(0, i); [connections[i], connections[j]] = [connections[j], connections[i]]; }
  return [n, connections];
}
